    {
      "id": "9fc2f73a-d4e4-4f57-8f7f-6e993fd932df",
      "sourceRow": 25,
      "sourceCell": "A25",
      "rawName": "휴머노이드 액추에이터·핸드",
      "name": "휴머노이드 액추에이터·핸드",
      "parentId": "620e4528-9f61-4894-a99b-d206f19c74e8",
      "rawRow": [
        "휴머노이드 액추에이터·핸드",
